 size.height * 0.98);//     pathBottom1.close();//     canvas.drawPath(pathBottom1, paint);// // الطبقة الوسطى (#C0A2DB)//     paint.color = const Color(0xFFC0A2DB).withValues(alpha: 0.5);//     var pathBottom2 = Path();//     pathBottom2.moveTo(0, size.height);//     pathBottom2.lineTo(size.width, size.height);//     pathBottom2.lineTo(size.width, size.height * 0.92);//     pathBottom2.quadraticBezierTo(size.width * 0.4, size.height * 0.95, 0, size.height * 0.85);//     pathBottom2.close();//     canvas.drawPath(pathBottom2, paint);//   }//   @override//   bool shouldRepaint(CustomPainter oldDelegate) => false;// }import 'package:flutter/material.dart';class LoginSignupBackground extends StatelessWidget {  final Widget child;  const LoginSignupBackground({super.key, required this.child});  @override  Widget build(BuildContext context) {    return Scaffold(      backgroundColor: const Color(0xFFFBF8FF),      body: Stack(        children: [          Positioned.fill(            child: CustomPaint(              painter: BackgroundPainter(),            ),          ),          SafeArea(child: child),        ],      ),    );  }}class BackgroundPainter extends CustomPainter {  @override  void paint(Canvas canvas, Size size) {    final paint = Paint()..style = PaintingStyle.fill;    // --- أولاً: رسم الأمواج السفلية ---    _drawBottomWaves(canvas, size, paint);    // --- ثانياً: الأشكال العلوية في الجهة اليمنى ---    // 1. التقوس العلوي الأيمن (خلفي)    final Rect rectRight1 = Rect.fromLTWH(size.width * 0.5, 0, size.width * 0.9, size.height * 0.25);    paint.shader = LinearGradient(      begin: Alignment.centerLeft,      end: Alignment.centerRight,      colors: [        const Color(0xFFB293CD),        const Color(0xFFE8DDF4),      ],    ).createShader(rectRight1);    var pathRight1 = Path();    pathRight1.moveTo(size.width, 0);    pathRight1.lineTo(size.width * 0.2, 0);    pathRight1.quadraticBezierTo(size.width * 0.7, size.height * 0.01, size.width, size.height * 0.07);    pathRight1.close();    canvas.drawPath(pathRight1, paint);    // 2. التقوس العلوي الأيمن (أمامي - الأغمق)    paint.shader = LinearGradient(      begin: Alignment.centerRight,      end: Alignment.centerLeft,      colors: [        const Color(0xFFB293CD),        const Color(0xFFE8DDF4),      ],    ).createShader(rectRight1);    var pathRight2 = Path();    pathRight2.moveTo(size.width, 0);    pathRight2.lineTo(size.width * 0.4, 0);    pathRight2.quadraticBezierTo(size.width * 0.97, size.height * 0.04, size.width, size.height * 0.01);    pathRight2.close();    canvas.drawPath(pathRight2, paint);    // --- ثالثاً: الأشكال العلوية في الجهة اليسرى ---    // 3. المثلث الخلفي (الأيسر)    final Rect rect1 = Rect.fromLTWH(0, 0, size.width, size.height * 0.35);    paint.shader = LinearGradient(      begin: Alignment.centerLeft,      end: Alignment.centerRight,      colors: [        Colors.white,        const Color(0xFFE8DDF4),        const Color(0xFFB293CD),      ],      stops: const [0.0, 0.03, 1.0],    ).createShader(rect1);    var path1 = Path();    path1.moveTo(0, 0);    path1.lineTo(size.width * 0.8, 0);    path1.quadraticBezierTo(size.width * 0.10, size.height * 0.10, 0, size.height * 0.18);    path1.close();    canvas.drawPath(path1, paint);    // 4. المثلث الأمامي (الأيسر)    final Rect rect2 = Rect.fromLTWH(0, 0, size.width, size.height * 0.28);    paint.shader = LinearGradient(      begin: Alignment.centerLeft,      end: Alignment.centerRight,      colors: [        const Color(0xFFB293CD),        const Color(0xFFE8DDF4),        Colors.white,      ],      stops: const [0.0, 0.75, 1.0],    ).createShader(rect2);    var path2 = Path();    path2.moveTo(0, 0);    path2.lineTo(size.width * 0.55, 0);    path2.quadraticBezierTo(size.width * 0.9, -size.height * 0.1, 0, size.height * 0.10);    path2.close();    canvas.drawPath(path2, paint);  }  void _drawBottomWaves(Canvas canvas, Size size, Paint paint) {    // 1. القوس السفلي الأصغر (يسار)    paint.shader = LinearGradient(      begin: Alignment.bottomLeft,      end: Alignment.bottomRight,      colors: [const Color(0xFFB293CD), const Color(0xFFFBF8FF)],    ).createShader(Rect.fromLTWH(0, size.height * 0.9, size.width, size.height * 0.1));    var pathLeftSmall = Path();    pathLeftSmall.moveTo(0, size.height);    pathLeftSmall.lineTo(size.width, size.height);    pathLeftSmall.lineTo(size.width, size.height * 0.92);    pathLeftSmall.quadraticBezierTo(size.width * 0.3, size.height * 0.9, 0, size.height * 0.8);    pathLeftSmall.close();    canvas.drawPath(pathLeftSmall, paint);    // 2. القوس السفلي الأكبر (يسار)    paint.shader = LinearGradient(        begin: Alignment.topLeft,        end: Alignment.bottomRight,        colors: [const Color(0xFFE8DDF4), const Color(0xFFB293CD)]    ).createShader(Rect.fromLTWH(0, size.height * 0.8, size.width, size.height * 0.2));    var pathLeftLarge = Path();    pathLeftLarge.moveTo(0, size.height);    pathLeftLarge.lineTo(size.width, size.height);    pathLeftLarge.lineTo(size.width, size.height * 0.85);    pathLeftLarge.quadraticBezierTo(size.width * 0.7, size.height * 0.97, 0, size.height * 0.85);    pathLeftLarge.close();    canvas.drawPath(pathLeftLarge, paint);    // 3. القوس الإضافي الأول (يمين - أفتح)    paint.shader = LinearGradient(      begin: Alignment.centerRight,      end: Alignment.centerLeft,      colors: [const Color(0xFFB293CD).withOpacity(0.5), const Color(0xFFB293CD)],      stops: const [0.0, 0.2],    ).createShader(Rect.fromLTWH(0, size.height * 0.8, size.width, size.height * 0.2));    var pathRight1 = Path();    pathRight1.moveTo(size.width, size.height);    pathRight1.lineTo(0, size.height);    pathRight1.lineTo(0, size.height * 0.99);    pathRight1.quadraticBezierTo(size.width * 0.67, size.height * 0.91, size.width, size.height * 0.78);    pathRight1.close();    canvas.drawPath(pathRight1, paint);    // 4. القوس الإضافي الثاني (يمين - أغمق)    paint.shader = LinearGradient(      begin: Alignment.bottomRight,      end: Alignment.bottomLeft,      colors: [const Color(0xFFB293CD), const Color(0xFFE8DDF4), const Color(0xFFE8DDF4)],    ).createShader(Rect.fromLTWH(0, size.height * 0.85, size.width, size.height * 0.15));    var pathRight2 = Path();    pathRight2.moveTo(size.width, size.height);    pathRight2.lineTo(0, size.height);    pathRight2.lineTo(0, size.height * 0.95);    pathRight2.quadraticBezierTo(size.width * 0.1, size.height * 0.99, size.width, size.height * 0.87);    pathRight2.close();    canvas.drawPath(pathRight2, paint);  }  @override  bool shouldRepaint(CustomPainter oldDelegate) => true;}